+instruct vabs(vecX dst, vecX src) %{
+  match(Set dst (AbsVF src));
+  match(Set dst (AbsVD src));
+  match(Set dst (AbsVB src));
+  match(Set dst (AbsVS src));
+  match(Set dst (AbsVI src));
+  match(Set dst (AbsVL src));
+  size(6);
+  ins_cost(DEFAULT_COST);
+  format %{ "VABS $dst,$src\t// absolute packed" %}
+  ins_encode %{
+    BasicType bt = Matcher::vector_element_basic_type(this);
+    switch (bt) {
+      case T_BYTE:
+        __ z_vlpb($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      case T_SHORT:
+        __ z_vlph($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      case T_INT:
+        __ z_vlpf($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      case T_LONG:
+        __ z_vlpg($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      case T_FLOAT:
+        __ z_vflpsb($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      case T_DOUBLE:
+        __ z_vflpdb($dst$$VectorRegister, $src$$VectorRegister);
+        break;
+      default:
+        ShouldNotReachHere();
+    }
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
