+instruct vshiftcntL(vecX dst, iRegI cnt) %{
+  match(Set dst (LShiftCntV cnt));
+  ins_cost(2 * DEFAULT_COST);
+  size(12);
+  ins_encode %{
+    __ z_vlvgf($dst$$VectorRegister, $cnt$$Register, 0); // insert into byte element 0
+    __ z_vrepf($dst$$VectorRegister, $dst$$VectorRegister, 0); // replicate to all 16 bytes
+  %}
+  ins_pipe(pipe_class_dummy);
+%}
+
